WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY discount_pct DESC, id) AS latest_rank FROM promotions) x WHERE latest_rank = 1), matched AS (SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM ranked src LEFT JOIN promotions pr ON COALESCE(src.channel, 'web') = pr.channel AND src.starts_on BETWEEN pr.starts_on AND pr.ends_on), base AS (SELECT id, channel, promo_code, starts_on, ends_on, promo_id, promotion_discount_pct, CAST(promotion_discount_pct AS INT) promotion_discount_pct_int, DATEDIFF(starts_on, ends_on) days_ends_on_to_starts_on, COALESCE(channel, 'OTHER') channel_clean FROM matched WHERE starts_on >= TO_DATE('2023-11-09') AND channel IS NOT NULL AND ends_on < '2023-10-16') SELECT id, channel, promo_code, starts_on, ends_on, promo_id, promotion_discount_pct, days_ends_on_to_starts_on, channel_clean, CASE WHEN promo_code RLIKE '^(SPRING10|VIP)$' THEN 'CORE' WHEN promo_code RLIKE '^(BUNDLE|WELCOME5)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS promo_code_zone FROM base ORDER BY days_ends_on_to_starts_on;
